CREATE TABLE q(test,expr); INSERT INTO q VALUES('1','b:G'),('2','b:G AND c:I'),('3','b:G NEAR c:I'),('4','a:C OR b:G OR c:K OR d:C'),('5','a:G OR b:G'); CREATE TABLE result AS SELECT test,'ASC' AS direction,(SELECT group_concat(docid,',') FROM (SELECT docid FROM t1 WHERE t1 MATCH q.expr ORDER BY docid ASC)) AS docs FROM q UNION ALL SELECT test,'DESC',(SELECT group_concat(docid,',') FROM (SELECT docid FROM t1 WHERE t1 MATCH q.expr ORDER BY docid DESC)) FROM q;